fn main() {
    let mut v = vec![10, 20, 30];

    println!("{:?}", v.get(1));
    println!("{:?}", v.get(9));

    if let Some(n) = v.get(9) {
        println!("found {n}");
    } else {
        println!("index 9 is empty");
    }

    let mut total = 0;
    for n in &v {
        total += n;
    }
    println!("total {total}");

    for n in &mut v {
        *n *= 2;
    }
    println!("{v:?}");
}

fn main() {
    let mut greeting = String::from("Hello");
    greeting.push_str(", world");
    greeting.push('!');
    println!("{greeting}");
    println!("bytes: {}", greeting.len());

    let name = String::from("Rust");
    let owned = greeting + " I am " + &name;
    println!("{owned}");

    let label = format!("{name} has {} letters", name.len());
    println!("{label}");
}

fn main() {
    let s = String::from("hello world");
    println!("{}", &s[0..5]);
    println!("{}", &s[6..11]);

    for c in s.chars() {
        print!("[{c}]");
    }
    println!();
}

use std::collections::HashMap;

fn main() {
    let words = ["red", "blue", "red", "green", "red"];
    let mut counts = HashMap::new();

    for w in words {
        let n = counts.entry(w).or_insert(0);
        *n += 1;
    }

    println!("red: {}", counts["red"]);
    println!("blue: {}", counts["blue"]);

    match counts.get("black") {
        Some(n) => println!("black: {n}"),
        None => println!("black: never seen"),
    }

    counts.insert("black", 9);
    println!("black now: {}", counts["black"]);
    println!("distinct words: {}", counts.len());
}

